def _vecinas_por_stem(
    cambiados: list[str], raiz: str, vigias: list[str]
) -> list[str] | None:
    """Vigias que mencionan el stem de cada archivo de codigo cambiado.

    Devuelve las vecinas encontradas MAS la vigia general del proyecto si existe,
    y una marca de que falta cubrir el archivo, en vez de None (bateria completa).
    Solo devuelve None si no hay ninguna vigia que cubra nada.

    Antes devolvia None si algun archivo de codigo cambiado (fuera de vigias/)
    no aparecia en ninguna vigia, y eso mandaba correr toda la bateria.
    """
    vecinas: list[str] = []
    for ruta in cambiados:
        if not _es_codigo(ruta):
            continue
        if ruta.startswith(_CARPETA_VIGIAS + "/"):
            continue
        stem = os.path.splitext(os.path.basename(ruta))[0]
        if not stem:
            continue
        encontrada = False
        for v in vigias:
            if _contiene_palabra(textos.get(v, ""), stem):
                vecinas.append(v)
                encontrada = True
        if not encontrada:
            # Archivo de codigo cambiado sin vecinas conocidas:
            # se anade la vigia general del proyecto si existe, y se marca
            # que falta cubrir ese archivo, en vez de correr toda la bateria.
            general = _vigia_general(raiz)
            if general is not None:
                vecinas.append(general)
            vecinas.append(_MARCA_FALTA_COBERTURA + stem)
    return vecinas
